export const QueryBackend = {
    CLICKHOUSE_ONLY: "clickhouse_only",
    SMITHDB_ONLY: "smithdb_only",
    DUAL: "dual",
};
/** Which backend(s) `/info`'s `instance_flags` indicate for run/trace queries. */
export function getQueryBackend(instanceFlags) {
    const flags = instanceFlags ?? {};
    const chEnabled = Boolean(flags.ch_query_enabled ?? true);
    const sdbEnabled = Boolean(flags.sdb_query_enabled ?? false);
    if (!chEnabled && sdbEnabled)
        return QueryBackend.SMITHDB_ONLY;
    if (chEnabled && sdbEnabled)
        return QueryBackend.DUAL;
    return QueryBackend.CLICKHOUSE_ONLY;
}
// Omitting selects from `/v2/runs/query` returns only the run ID.
const V2_RUN_SELECTS = [
    "ID",
    "NAME",
    "RUN_TYPE",
    "STATUS",
    "START_TIME",
    "END_TIME",
    "INPUTS",
    "OUTPUTS",
    "PARENT_RUN_IDS",
    "PROJECT_ID",
    "TRACE_ID",
    "DOTTED_ORDER",
    "REFERENCE_EXAMPLE_ID",
    "ERROR",
];
export function v2RunToRun(run) {
    if (run.id == null || run.name == null || run.run_type == null) {
        throw new Error("V2 run response is missing required fields.");
    }
    return {
        id: run.id,
        name: run.name,
        run_type: run.run_type.toLowerCase(),
        start_time: run.start_time,
        end_time: run.end_time,
        trace_id: run.trace_id,
        session_id: run.project_id,
        parent_run_id: run.parent_run_ids?.at(-1),
        dotted_order: run.dotted_order,
        reference_example_id: run.reference_example_id,
        inputs: run.inputs ?? {},
        outputs: run.outputs,
        error: run.error ?? undefined,
        status: run.status?.toLowerCase(),
    };
}
export async function loadTracesV2(client, project, options) {
    const runs = [];
    const pager = client.runs.queryV2({
        project_ids: [project.id],
        min_start_time: new Date(project.start_time).toISOString(),
        max_start_time: new Date(project.end_time ?? Date.now()).toISOString(),
        is_root: options.isRoot,
        selects: V2_RUN_SELECTS,
    });
    for await (const run of pager) {
        runs.push(v2RunToRun(run));
    }
    return runs;
}
